document.addEventListener('input',async e=>{
 if(e.target.matches('[data-indicator]')){editing.answers[e.target.dataset.indicator]=Number(e.target.value);dirty=true;const n=Object.keys(editing.answers).length;document.getElementById('answer-count').textContent=`${n} / 7 terjawab`;document.getElementById('answer-progress').value=n;const i=data.indicators.find(i=>Number(i.id)===Number(e.target.dataset.indicator));document.getElementById(`check-${i.id}`).innerHTML=icon('circle-check')+esc(i.name);document.getElementById(`check-${i.id}`).classList.add('answered');icons();}
 if(e.target.id==='feedback')dirty=true;
 if(e.target.dataset.search){const id=e.target.id,pos=e.target.selectionStart,t=tbl(e.target.dataset.search);t.q=e.target.value;t.page=1;await rerender();const input=document.getElementById(id);if(input){input.focus();input.setSelectionRange(pos,pos);}}
});
